SELECT

FROM risk_warning

    deleted = 0

        AND project_id = #{param.projectId}


        AND warning_type = #{param.warningType}


        AND warning_level = #{param.warningLevel}


        AND warning_title LIKE CONCAT('%', #{param.warningTitle}, '%')


        AND warning_status = #{param.warningStatus}


        AND handle_status = #{param.handleStatus}


        AND handle_person LIKE CONCAT('%', #{param.handlePerson}, '%')


        AND warning_time >= #{param.startDate}


        AND warning_time <= #{param.endDate}


ORDER BY warning_level DESC, warning_time DESC, create_time DESC

SELECT COUNT(*) as totalWarnings, SUM(CASE WHEN warning_level = 1 THEN 1 ELSE 0 END) as lowLevelCount, SUM(CASE WHEN warning_level = 2 THEN 1 ELSE 0 END) as mediumLevelCount, SUM(CASE WHEN warning_level = 3 THEN 1 ELSE 0 END) as highLevelCount, SUM(CASE WHEN warning_level = 4 THEN 1 ELSE 0 END) as criticalLevelCount, SUM(CASE WHEN warning_status = 1 THEN 1 ELSE 0 END) as activeWarnings, SUM(CASE WHEN warning_status = 2 THEN 1 ELSE 0 END) as resolvedWarnings, SUM(CASE WHEN warning_status = 3 THEN 1 ELSE 0 END) as ignoredWarnings, SUM(CASE WHEN handle_status = 1 THEN 1 ELSE 0 END) as pendingHandle, SUM(CASE WHEN handle_status = 2 THEN 1 ELSE 0 END) as handlingCount, SUM(CASE WHEN handle_status = 3 THEN 1 ELSE 0 END) as handledCount FROM risk_warning
deleted = 0
AND project_id = #{projectId}

SELECT
FROM risk_warning
deleted = 0 AND warning_status = 1 AND warning_level >= #{minLevel}
AND project_id = #{projectId}
ORDER BY warning_level DESC, warning_time DESC

SELECT warning_type, COUNT(*) as count, SUM(CASE WHEN warning_status = 1 THEN 1 ELSE 0 END) as activeCount, SUM(CASE WHEN warning_level >= 3 THEN 1 ELSE 0 END) as highLevelCount FROM risk_warning
deleted = 0
AND project_id = #{projectId}
AND warning_time >= #{startDate}
AND warning_time <= #{endDate}
GROUP BY warning_type ORDER BY count DESC

SELECT DATE_FORMAT(warning_time, '%Y-%m') as month, COUNT(*) as totalCount, SUM(CASE WHEN warning_level >= 3 THEN 1 ELSE 0 END) as highLevelCount, SUM(CASE WHEN warning_status = 2 THEN 1 ELSE 0 END) as resolvedCount FROM risk_warning
deleted = 0
AND project_id = #{projectId}
AND warning_time >= #{startDate}
AND warning_time <= #{endDate}
GROUP BY DATE_FORMAT(warning_time, '%Y-%m') ORDER BY month DESC LIMIT 12

